import {
  getActiveCompanyId,
  getAuthToken,
  hasValidAuthToken,
  normCompanyCode,
  setActiveCompanyId,
} from '@linm-soft-org/linm-web-common-components';
import { readJwtHomeCompanyId, readJwtTenantScope } from './jwtTenantClaims';

export interface ActiveCompanyValidation {
  /** Value after validate (may equal stored or JWT home). */
  companyId: string | null;
  /** Raw storage before validate. */
  stored: string | null;
  jwtHome: string | undefined;
  allowedCompanyIds: string[];
  canViewAll: boolean;
  /** Storage was corrected (e.g. LINM → UBNA). */
  corrected: boolean;
}

function setActiveCompanyIdIfChanged(companyId: string): boolean {
  const next = normCompanyCode(companyId);
  const current = getActiveCompanyId();
  if (current === next) return false;
  setActiveCompanyId(next);
  return true;
}

type ComputeOptions = { write: boolean };

/**
 * Hospital SSOT — JWT allowlist vs `linm_active_company_id`.
 * When stored ∈ allowlist → keep stored (shell switch). Else → JWT home.
 */
function computeActiveCompanyValidation(
  options: ComputeOptions,
): ActiveCompanyValidation {
  const stored = getActiveCompanyId();

  if (!hasValidAuthToken()) {
    return {
      companyId: stored,
      stored,
      jwtHome: undefined,
      allowedCompanyIds: [],
      canViewAll: false,
      corrected: false,
    };
  }

  const jwtHome = readJwtHomeCompanyId();
  if (!jwtHome) {
    return {
      companyId: stored,
      stored,
      jwtHome: undefined,
      allowedCompanyIds: [],
      canViewAll: false,
      corrected: false,
    };
  }

  const jwtScope = readJwtTenantScope();
  if (jwtScope.canViewAll) {
    return {
      companyId: stored ?? jwtHome,
      stored,
      jwtHome,
      allowedCompanyIds: [],
      canViewAll: true,
      corrected: false,
    };
  }

  const allowedCompanyIds =
    jwtScope.allowedCompanyIds.length > 0
      ? jwtScope.allowedCompanyIds.map(normCompanyCode)
      : [normCompanyCode(jwtHome)];

  const homeNorm = normCompanyCode(jwtHome);
  const storedNorm = stored ? normCompanyCode(stored) : '';

  if (!storedNorm || !allowedCompanyIds.includes(storedNorm)) {
    const corrected = options.write
      ? setActiveCompanyIdIfChanged(homeNorm)
      : storedNorm !== homeNorm;
    return {
      companyId: homeNorm,
      stored,
      jwtHome: homeNorm,
      allowedCompanyIds,
      canViewAll: false,
      corrected,
    };
  }

  return {
    companyId: storedNorm,
    stored,
    jwtHome: homeNorm,
    allowedCompanyIds,
    canViewAll: false,
    corrected: false,
  };
}

/**
 * Read-only — for fetch interceptors (no storage write, no `linm:company:changed`).
 */
export function readActiveCompanyIdForRequest(): string | null {
  return computeActiveCompanyValidation({ write: false }).companyId;
}

/**
 * Boot / reconcile — may write storage when stale ∉ JWT allowlist.
 */
export function validateAndGetActiveCompanyId(): ActiveCompanyValidation {
  return computeActiveCompanyValidation({ write: true });
}

/** @returns true when storage was corrected to match JWT. */
export function syncActiveCompanyFromJwt(): boolean {
  return validateAndGetActiveCompanyId().corrected;
}

/** DevTools — log mismatch; reconcile uses write path once. */
export function debugActiveCompanyState(): ActiveCompanyValidation {
  const dry = computeActiveCompanyValidation({ write: false });
  const tokenPresent = Boolean(getAuthToken());
  console.info('[tenant] active company state', {
    stored: dry.stored,
    jwtHome: dry.jwtHome,
    effective: dry.companyId,
    allowed: dry.allowedCompanyIds,
    canViewAll: dry.canViewAll,
    wouldCorrect: dry.corrected,
    tokenPresent,
    hasValidAuthToken: hasValidAuthToken(),
  });
  return validateAndGetActiveCompanyId();
}
